# =============================================================================
# Chapter 13 values: Ethics in Statistics and Data Integrity
#
# Run from the project root:
#   Rscript r_code/figures/chapter_13_values.R
#
# Chapter 13 uses no dataset. This script records the false-positive
# probabilities behind Figure 13.2 and notes the four conceptual tables. The
# figures are generated by r_code/figures/chapter_13.R.
# figures/chapter_13/values.yml is generated by save_book_values(); do not edit
# it by hand.
# =============================================================================

source("r_code/figures/_book_figs.R")

# ---- False-positive probabilities ------------------------------------------

alpha <- 0.05
tests <- c(1, 5, 10, 20, 50)
probability <- 1 - (1 - alpha)^tests

false_positive <- data.frame(
  tests = tests,
  probability = round(probability, 4),
  percent = round(100 * probability, 1)
)

# ---- Values registry --------------------------------------------------------

values <- list(
  false_positive_probability = list(
    assumption = paste(
      "Independent tests with a true null for every test"
    ),
    alpha = alpha,
    table = false_positive,
    twenty_test_percent = round(100 * (1 - (1 - alpha)^20), 1),
    note = paste(
      "The probability of at least one false positive is 1 - (1 - alpha)^k",
      "for k independent tests. At 20 tests the probability is 64.2%, which",
      "supports the chapter's claim that at least one false positive is",
      "likely. The figure rounds the labels to whole percentages."
    )
  ),
  table_13_1 = list(
    note = paste(
      "Data governance versus data stewardship. Conceptual comparison; no",
      "calculated values."
    )
  ),
  table_13_2 = list(
    note = paste(
      "The three IRB review concepts: human subjects, minimal risk, and",
      "vulnerable populations. Conceptual comparison; no calculated values."
    )
  ),
  table_13_3 = list(
    note = paste(
      "Anonymity versus confidentiality. Conceptual comparison; no",
      "calculated values."
    )
  ),
  table_13_4 = list(
    note = paste(
      "P-hacking tactics and ethical alternatives. Conceptual comparison; no",
      "calculated values."
    )
  ),
  figures = list(
    figure_13_1 = list(
      note = paste(
        "Secure data workflow diagram. The four stages are gather, transfer,",
        "de-identify, and store. The master key branches to a separate",
        "restricted folder."
      )
    ),
    figure_13_2 = list(
      note = paste(
        "False-positive probability for 1, 5, 10, 20, and 50 independent",
        "tests at alpha = 0.05: 5.0%, 22.6%, 40.1%, 64.2%, and 92.3%."
      )
    )
  )
)

save_book_values(
  chapter = 13,
  values = values,
  conventions = list(
    dataset = paste(
      "Chapter 13 is conceptual and uses no dataset. The only calculated",
      "values are the false-positive probabilities for Figure 13.2."
    ),
    false_positive = paste(
      "The calculation assumes independent tests and a true null for every",
      "test. The probability of at least one false positive is",
      "1 - (1 - alpha)^k. The figure uses alpha = 0.05 and k = 1, 5, 10, 20,",
      "and 50."
    ),
    tables = paste(
      "Tables 13.1 through 13.4 are conceptual comparisons. They summarize",
      "definitions and examples already in the prose; no values are",
      "calculated."
    ),
    workflow = paste(
      "Figure 13.1 is a diagram of the workflow described in Section 13.4.",
      "It shows the master key stored separately from the de-identified",
      "transcripts."
    )
  ),
  source = "r_code/figures/chapter_13_values.R"
)

# ---- Console summary --------------------------------------------------------

cat("\n--- Chapter 13 summary ---\n")
cat("False-positive probabilities:\n")
print(false_positive)
cat("At 20 tests:", round(100 * (1 - (1 - alpha)^20), 1), "%\n")
